import { computed, ref } from 'vue'
import { useUserStore } from '@/stores/userStore'

/**
 * Stub for the deleted useCurrentUser composable.
 * Provides local-auth compatible replacements for cloud auth features.
 */
export function useCurrentUser() {
  const userStore = useUserStore()

  const isLoggedIn = computed(() => !!userStore.currentUserId)
  const loading = ref(false)
  const isApiKeyLogin = ref(false)
  const isEmailProvider = ref(true)
  const userDisplayName = computed(
    () => userStore.currentUser?.username ?? userStore.currentUserId ?? ''
  )
  const userEmail = computed(() => '')
  const userPhotoUrl = ref<string | null>(null)
  const providerName = ref('Local')
  const providerIcon = ref('pi pi-key')
  const resolvedUserInfo = computed(() =>
    userStore.currentUserId ? { id: userStore.currentUserId } : null
  )

  async function handleSignOut() {
    await fetch('/api/logout', { method: 'POST' })
    await userStore.logout()
    window.location.href = '/login'
  }

  function handleSignIn() {
    window.location.href = '/login'
  }

  function onUserResolved(_callback: (user: unknown) => void) {
    // No-op: cloud auth removed
  }

  function onTokenRefreshed(_callback: () => void) {
    // No-op: cloud auth removed
  }

  function onUserLogout(_callback: () => void) {
    // No-op: cloud auth removed
  }

  return {
    isLoggedIn,
    loading,
    isApiKeyLogin,
    isEmailProvider,
    userDisplayName,
    userEmail,
    userPhotoUrl,
    providerName,
    providerIcon,
    resolvedUserInfo,
    handleSignOut,
    handleSignIn,
    onUserResolved,
    onTokenRefreshed,
    onUserLogout
  }
}
